<?php
require_once __DIR__.'/../includes/init.php';require_login();$page_title='Fee Payments';$students=$pdo->query("SELECT id,admission_no,full_name FROM students WHERE status='active' ORDER BY full_name")->fetchAll();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$q=$pdo->prepare('INSERT INTO fee_payments(student_id,receipt_no,amount,payment_method,paid_on,received_by,notes) VALUES(?,?,?,?,?,?,?)');$q->execute([(int)$_POST['student_id'],trim($_POST['receipt_no']),(float)$_POST['amount'],$_POST['payment_method'],$_POST['paid_on'],$_SESSION['user_id'],trim($_POST['notes']??'')]);flash('Fee payment recorded.');go('fees/index.php');}catch(Throwable $e){$err='Payment not saved. Check receipt number and fields.';}}
$rows=$pdo->query('SELECT p.receipt_no,p.amount,p.payment_method,p.paid_on,s.full_name,s.admission_no FROM fee_payments p JOIN students s ON s.id=p.student_id ORDER BY p.id DESC LIMIT 200')->fetchAll();require __DIR__.'/../includes/header.php';?><h1>Fee Payments</h1><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif;?><div class="panel"><h2>Record payment</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid"><div><label>Student</label><select name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=h($s['admission_no'].' - '.$s['full_name'])?></option><?php endforeach;?></select></div><div><label>Receipt number</label><input name="receipt_no" required></div><div><label>Amount</label><input type="number" step="0.01" min="0.01" name="amount" required></div><div><label>Method</label><select name="payment_method"><option>Cash</option><option>Bank</option><option>Online</option><option>Cheque</option></select></div><div><label>Payment date</label><input type="date" name="paid_on" value="<?=date('Y-m-d')?>" required></div><div><label>Notes</label><input name="notes"></div></div><button>Save payment</button></form></div><div class="panel"><h2>Recent payments</h2><div class="tablewrap"><table><tr><th>Receipt</th><th>Student</th><th>Admission</th><th>Amount</th><th>Method</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['receipt_no'])?></td><td><?=h($r['full_name'])?></td><td><?=h($r['admission_no'])?></td><td><?=number_format((float)$r['amount'],2)?></td><td><?=h($r['payment_method'])?></td><td><?=h($r['paid_on'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>